// The certificate of acceptance: a PDF that proves, for one company, which contract documents (terms, privacy policy, data processing
// agreement) its administrator accepted, in which version, when and from where. It is generated by itself when a company accepts and kept
// in the company's Biblioteca (audience "Administrativo"), so it can be shown to whoever asks for proof of consent (a data provider, a
// client's auditor...). Relative imports only.
import { createHash, randomUUID } from 'node:crypto';
import { put } from '@vercel/blob';
import { jsPDF } from 'jspdf';
import { recordAudit } from '../audit';
import { sql } from '../db';

export const CERTIFICATE_DOCUMENTS = ['terms', 'privacy', 'dpa'] as const;
export type CertificateDocument = (typeof CERTIFICATE_DOCUMENTS)[number];

export const CERTIFICATE_LABELS: Record<CertificateDocument, string> = {
  terms: 'Termos de Uso',
  privacy: 'Política de Privacidade',
  dpa: 'Acordo de Tratamento de Dados (DPA)',
};

export const CERTIFICATE_CATEGORY = 'Contrato e privacidade';
export const certificateTitle = (version: string) => `Comprovante de aceite dos termos (versão ${version})`;

export type CertificateRow = { document: CertificateDocument; version: string; acceptedAt: string; who: string | null; role: string | null; ip: string | null };
export type CertificateCompany = { name: string; legalName: string | null; document: string | null; slug: string };

// ------------------------------------------------------------------------------------------------------------------ pure pieces

/** The start of the SHA-256 of the "document|version|moment (UTC)" lines, in the order of the acceptances: anyone holding the lines can recompute it. */
export function verificationCode(rows: Array<Pick<CertificateRow, 'document' | 'version' | 'acceptedAt'>>): string {
  const canonical = rows.map((row) => `${row.document}|${row.version}|${row.acceptedAt}`).join('\n');
  return createHash('sha256').update(canonical, 'utf8').digest('hex').slice(0, 16).toUpperCase();
}

/** "04/11/2026 às 14:53:44" in Brasília time. */
export function formatBrasilia(iso: string, seconds = true): string {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' })
      .formatToParts(new Date(iso))
      .map((part) => [part.type, part.value]),
  );
  return `${parts.day}/${parts.month}/${parts.year} às ${parts.hour}:${parts.minute}${seconds ? `:${parts.second}` : ''}`;
}

/** "187.122.137.xxx": the last number stays out of the document (the whole address stays in the record, available on request). */
export function maskIp(ip: string | null | undefined): string {
  const parts = String(ip ?? '').split('.');
  return parts.length === 4 ? `${parts.slice(0, 3).join('.')}.xxx` : ip ? 'registrado' : 'não registrado';
}

export function formatCnpj(value: string | null | undefined): string {
  const digits = String(value ?? '').replace(/\D/g, '');
  return digits.length === 14 ? `${digits.slice(0, 2)}.${digits.slice(2, 5)}.${digits.slice(5, 8)}/${digits.slice(8, 12)}-${digits.slice(12)}` : String(value ?? '') || '—';
}

const GREEN: [number, number, number] = [20, 83, 45];
const GRAY: [number, number, number] = [107, 114, 128];
const INK: [number, number, number] = [31, 41, 55];

/** The PDF itself (A4, one page): the company, the table of acceptances, the roles, what it proves and does not, and the verification code. */
export function buildCertificatePdf(input: { company: CertificateCompany; rows: CertificateRow[]; issuedAt: string }): Uint8Array {
  const { company, rows, issuedAt } = input;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const left = 18;
  const width = 174;
  let y = 24;

  const color = (rgb: [number, number, number]) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);
  const write = (text: string, size: number, style: 'normal' | 'bold', rgb: [number, number, number], gap = 1.2) => {
    doc.setFont('helvetica', style);
    doc.setFontSize(size);
    color(rgb);
    const lines = doc.splitTextToSize(text, width) as string[];
    for (const line of lines) {
      doc.text(line, left, y);
      y += size * 0.44 + gap;
    }
  };
  const heading = (text: string) => {
    y += 4;
    write(text, 11.5, 'bold', GREEN, 1.6);
  };
  const pair = (label: string, value: string) => {
    doc.setFontSize(10.5);
    doc.setFont('helvetica', 'normal');
    color(GRAY);
    doc.text(`${label}:`, left, y);
    const at = left + doc.getTextWidth(`${label}: `);
    doc.setFont('helvetica', 'bold');
    color(INK);
    doc.text(value, at, y);
    y += 6;
  };

  write('Comprovante de aceite de documentos contratuais', 17, 'bold', GREEN, 1.5);
  write(`NextRotta · nextrotta.app · emitido em ${formatBrasilia(issuedAt, false)} (horário de Brasília)`, 10, 'normal', GRAY, 1);

  heading('Empresa contratante');
  pair('Nome', company.name);
  pair('Razão social', company.legalName || '—');
  pair('CNPJ', formatCnpj(company.document));
  pair('Endereço na plataforma', `${company.slug}.nextrotta.app`);

  heading('Aceites registrados');
  write('Registros gerados automaticamente pela plataforma no momento em que o administrador da empresa aceitou cada documento ao acessar o sistema.', 10, 'normal', INK);
  y += 1;

  // the table
  const columns = [
    { title: 'Documento', width: 50 },
    { title: 'Versão', width: 20 },
    { title: 'Data e hora (Brasília)', width: 36 },
    { title: 'Quem aceitou', width: 44 },
    { title: 'IP', width: 24 },
  ];
  doc.setFillColor(232, 243, 236);
  doc.rect(left, y - 4.5, width, 8, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  color(INK);
  let x = left + 1.5;
  for (const column of columns) {
    doc.text(column.title, x, y);
    x += column.width;
  }
  y += 6;
  for (const row of rows) {
    const cells = [
      CERTIFICATE_LABELS[row.document],
      row.version,
      formatBrasilia(row.acceptedAt),
      `${row.who || '—'} (perfil ${row.role === 'admin' ? 'administrador' : row.role || '—'})`,
      maskIp(row.ip),
    ];
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9.5);
    const wrapped = cells.map((cell, index) => doc.splitTextToSize(cell, columns[index].width - 3) as string[]);
    const lines = Math.max(...wrapped.map((cell) => cell.length));
    doc.setDrawColor(209, 213, 219);
    doc.setLineWidth(0.2);
    doc.line(left, y - 4.2, left + width, y - 4.2);
    let cellX = left + 1.5;
    wrapped.forEach((cell, index) => {
      doc.setFont('helvetica', index === 0 ? 'bold' : 'normal');
      cell.forEach((line, lineIndex) => doc.text(line, cellX, y + lineIndex * 4.4));
      cellX += columns[index].width;
    });
    y += lines * 4.4 + 3.2;
  }
  y += 1;
  write('Origem de todos os aceites: aplicativo (janela de aceite exibida no acesso). O endereço IP completo fica guardado no registro da plataforma e é omitido aqui; está disponível mediante solicitação.', 8.5, 'normal', GRAY);

  heading('Papéis previstos nos documentos aceitos');
  write('Conforme os Termos de Uso (cláusula 5.3) e o Acordo de Tratamento de Dados (DPA), em relação aos dados que a empresa cliente cadastra na plataforma, a empresa cliente é a controladora e a NextRotta é a operadora, que trata os dados por conta e conforme as instruções da controladora.', 10, 'normal', INK);

  heading('O que este comprovante atesta');
  write('Atesta o aceite dos três documentos acima, com as datas e versões indicadas. Não atesta, por si só, a autorização da empresa para consultas específicas a órgãos públicos; essa autorização, quando existir, é apresentada em documento próprio.', 10, 'normal', INK);

  y += 5;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(11);
  color(INK);
  doc.text('Código de verificação: ', left, y);
  doc.setFont('helvetica', 'bold');
  doc.text(verificationCode(rows), left + doc.getTextWidth('Código de verificação: '), y);
  y += 6;
  write('O código é o início do resumo SHA-256 das linhas "documento|versão|data em UTC" dos três aceites, na ordem acima, e pode ser recalculado a partir delas.', 8.5, 'normal', GRAY);
  write('Contato: contato@nextrotta.com', 8.5, 'normal', GRAY);

  return new Uint8Array(doc.output('arraybuffer'));
}

// ------------------------------------------------------------------------------------------------------------- the company's file

/** Where the PDF goes. The real one is the private blob store; the tests give their own. */
export type CertificateStore = (pathname: string, bytes: Uint8Array) => Promise<{ url: string }>;

const blobStore: CertificateStore = async (pathname, bytes) => {
  const blob = await put(pathname, Buffer.from(bytes), { access: 'private', contentType: 'application/pdf' });
  return { url: blob.url };
};

/** The latest acceptance of each of the three documents, oldest first. */
export async function loadCertificateRows(organizationId: string): Promise<CertificateRow[]> {
  const rows = await sql`
    SELECT DISTINCT ON (a.document) a.document, a.version, a.accepted_at, a.ip, u.name AS who, u.role
    FROM legal_acceptances a LEFT JOIN users u ON u.id = a.user_id
    WHERE a.organization_id = ${organizationId} AND a.document = ANY(${CERTIFICATE_DOCUMENTS as unknown as string[]})
    ORDER BY a.document, a.accepted_at DESC
  `;
  return rows
    .map((row) => ({
      document: row.document as CertificateDocument,
      version: String(row.version),
      acceptedAt: new Date(row.accepted_at as string).toISOString(),
      who: (row.who as string | null) ?? null,
      role: (row.role as string | null) ?? null,
      ip: (row.ip as string | null) ?? null,
    }))
    .sort((a, b) => a.acceptedAt.localeCompare(b.acceptedAt) || CERTIFICATE_DOCUMENTS.indexOf(a.document) - CERTIFICATE_DOCUMENTS.indexOf(b.document));
}

export type CertificateResult =
  | { status: 'created'; id: string; title: string }
  | { status: 'exists'; id: string; title: string }
  | { status: 'incomplete' };

/**
 * Generates the company's certificate and keeps it in its Biblioteca. One per version of the documents: asking again for the same version does
 * nothing (`exists`), unless `force`, which archives the previous one and makes a new one. A company that has not accepted all three is `incomplete`.
 */
export async function generateAcceptanceCertificate(
  organizationId: string,
  options: { force?: boolean; store?: CertificateStore; actorId?: string | null } = {},
): Promise<CertificateResult> {
  const rows = await loadCertificateRows(organizationId);
  if (rows.length < CERTIFICATE_DOCUMENTS.length) return { status: 'incomplete' };

  const version = rows.map((row) => row.version).sort().at(-1) as string;
  const title = certificateTitle(version);
  const existing = await sql`
    SELECT id FROM library_documents WHERE organization_id = ${organizationId} AND category = ${CERTIFICATE_CATEGORY} AND title = ${title} AND deleted_at IS NULL
  `;
  if (existing.length && !options.force) return { status: 'exists', id: String(existing[0].id), title };

  const [company] = await sql`SELECT name, legal_name, document, slug FROM organizations WHERE id = ${organizationId}`;
  const bytes = buildCertificatePdf({
    company: { name: String(company.name), legalName: (company.legal_name as string | null) ?? null, document: (company.document as string | null) ?? null, slug: String(company.slug) },
    rows,
    issuedAt: new Date().toISOString(),
  });

  const id = randomUUID();
  const fileName = `${id}-comprovante-de-aceite-${version}.pdf`;
  const stored = await (options.store ?? blobStore)(`library/${organizationId}/${fileName}`, bytes);

  if (existing.length) {
    // Archived, never erased: the earlier certificate stays in the company's trash like any document.
    await sql`UPDATE library_documents SET deleted_at = NOW(), updated_at = NOW() WHERE organization_id = ${organizationId} AND category = ${CERTIFICATE_CATEGORY} AND title = ${title} AND deleted_at IS NULL`;
  }
  await sql`
    INSERT INTO library_documents (organization_id, id, title, category, audience, type, url, file_name, file_size, uploaded_by)
    VALUES (${organizationId}, ${id}, ${title}, ${CERTIFICATE_CATEGORY}, 'Administrativo', 'PDF', ${stored.url}, ${fileName}, ${bytes.length}, 'NextRotta (automático)')
  `;
  await recordAudit({
    organizationId,
    actorId: options.actorId ?? null,
    actorRole: options.actorId ? 'platform_owner' : 'system',
    impersonationId: null,
    action: 'legal.certificate_generated',
    targetType: 'organization',
    targetId: organizationId,
    details: { version, replaced: existing.length > 0 },
  });
  return { status: 'created', id, title };
}

/** After an acceptance: make the certificate, and never let a failure here undo or delay the acceptance itself. */
export async function ensureAcceptanceCertificate(organizationId: string, store?: CertificateStore): Promise<CertificateResult | null> {
  try {
    return await generateAcceptanceCertificate(organizationId, { store });
  } catch (error) {
    console.error('[legal] could not generate the acceptance certificate for', organizationId, error);
    return null;
  }
}

export type CertificateFile = { id: string; title: string; createdAt: string; size: number | null; fileName: string | null };

/** The certificates the company has now (newest first). */
export async function listCertificates(organizationId: string): Promise<CertificateFile[]> {
  const rows = await sql`
    SELECT id, title, created_at, file_size, file_name FROM library_documents
    WHERE organization_id = ${organizationId} AND category = ${CERTIFICATE_CATEGORY} AND title LIKE 'Comprovante de aceite%' AND deleted_at IS NULL
    ORDER BY created_at DESC
  `;
  return rows.map((row) => ({
    id: String(row.id),
    title: String(row.title),
    createdAt: new Date(row.created_at as string).toISOString(),
    size: row.file_size == null ? null : Number(row.file_size),
    fileName: (row.file_name as string | null) ?? null,
  }));
}

/** The private address of one certificate of the company (null when it is not theirs). */
export async function getCertificateFile(organizationId: string, id: string): Promise<{ url: string; fileName: string } | null> {
  const rows = await sql`
    SELECT url, file_name FROM library_documents
    WHERE id = ${id} AND organization_id = ${organizationId} AND category = ${CERTIFICATE_CATEGORY} AND title LIKE 'Comprovante de aceite%' AND deleted_at IS NULL
  `;
  return rows[0]?.url ? { url: String(rows[0].url), fileName: String(rows[0].file_name || 'comprovante-de-aceite.pdf') } : null;
}
